pub fn fibonacci(n: usize) -> Vec<i32> {
    // We assume n >= 2 as per the problem statement.
    let mut result = Vec::with_capacity(n);
    result.push(0);
    result.push(1);

    // Loop from i = 2 to n-1, maintaining that:
    //  1) result.len() == i
    //  2) result[0] == 0, result[1] == 1
    //  3) for all j in 2..i, result[j] == result[j-1] + result[j-2]
    for i in 2..n {
        #[verifier::invariant(result.len() == i)]
        #[verifier::invariant(result[0] == 0)]
        #[verifier::invariant(result[1] == 1)]
        #[verifier::invariant(forall(|j: usize| 2 <= j && j < i ==>
            result[j] == result[j - 1] + result[j - 2]
        ))]
        #[verifier::decreases(n - i)]
        {
            // Since the Fibonacci number at index n-1 is guaranteed < 2^31,
            // this addition cannot overflow an i32.
            let next = result[i - 1] + result[i - 2];
            result.push(next);
        }
    }

    result
}

